head.b:skin:
:root {
  color-scheme: dark;
  --bg: #0a0a0b;
  --surface: #151517;
  --surface-hover: #202024;
  --text: #f4f4f5;
  --muted: #a6a6ae;
  --accent: #4aa8ff;
  --border: rgba(255,255,255,.1);
  --width: 1160px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.7 Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
}
a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent); }
.wrap { width: min(var(--width), calc(100% - 40px)); margin: 0 auto; }
.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(10,10,11,.94);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(14px);
}
.header-inner {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.brand {
  font-size: 1.05rem;
  font-weight: 750;
  letter-spacing: .09em;
  text-transform: uppercase;
  white-space: nowrap;
}
.brand-dot { color: var(--accent); margin-right: 8px; }
.nav { display: flex; flex-wrap: wrap; gap: 4px; justify-content: flex-end; }
.nav a {
  padding: 8px 11px;
  border-radius: 999px;
  color: var(--muted);
  font-size: .86rem;
}
.nav a:hover { background: var(--surface-hover); color: var(--text); }
.intro { padding: clamp(58px, 10vw, 112px) 0 54px; }
.eyebrow {
  color: var(--accent);
  font-size: .76rem;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}
h1, h2, h3 { line-height: 1.2; }
.intro h1 {
  max-width: 820px;
  margin: 16px 0;
  font-size: clamp(2.4rem, 7vw, 5.3rem);
  letter-spacing: -.055em;
}
.intro p { max-width: 650px; color: var(--muted); font-size: 1.08rem; }
.content { padding-bottom: 76px; }
.section-title { margin: 0 0 24px; font-size: 1.55rem; }
.posts-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.post-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
  transition: transform .2s ease, border-color .2s ease;
}
.post-card:hover { transform: translateY(-3px); border-color: rgba(74,168,255,.48); }
.post-thumb { display: block; width: 100%; aspect-ratio: 16/9; object-fit: cover; background: var(--surface-hover); }
.post-card-body { padding: 20px; }
.labels { display: flex; flex-wrap: wrap; gap: 7px; margin-bottom: 12px; }
.labels a {
  color: var(--accent);
  font-size: .72rem;
  font-weight: 650;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.post-card h2 { margin: 0 0 10px; font-size: 1.2rem; }
.post-card p, .post-meta { margin: 0; color: var(--muted); font-size: .9rem; }
.post-meta { margin-top: 15px; font-size: .78rem; }
.blog-posts, .post-outer-container, .post-outer {
  color: var(--text);
}
.post-outer {
  margin: 0 0 20px;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
}
.post-title, .post-title a { color: var(--text); }
.post-body { color: var(--muted); }
.post-body img { max-width: 100%; height: auto; }
.post-footer, .post-header, .date-header { color: var(--muted); }
.article { max-width: 820px; margin: 0 auto; }
.article h1 { margin: 12px 0; font-size: clamp(2rem, 5vw, 3.5rem); letter-spacing: -.04em; }
.article-body { margin-top: 32px; overflow-wrap: anywhere; }
.article-body img { max-width: 100%; height: auto; border-radius: 10px; }
.article-body iframe { max-width: 100%; }
.article-body a { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.pager { display: flex; justify-content: space-between; gap: 16px; margin-top: 32px; }
.pager a, .read-more {
  display: inline-block;
  padding: 10px 15px;
  border: 1px solid var(--border);
  border-radius: 999px;
}
.site-footer { padding: 28px 0; border-top: 1px solid var(--border); color: var(--muted); font-size: .84rem; }
@media (max-width: 800px) {
  .header-inner { align-items: flex-start; flex-direction: column; justify-content: center; gap: 8px; padding: 14px 0; }
  .nav { justify-content: flex-start; }
  .nav a { padding: 6px 9px; }
  .posts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 540px) {
  .wrap { width: min(100% - 28px, var(--width)); }
  .posts-grid { grid-template-columns: 1fr; }
}
